/// Main playback thread function.
pub(super) fn run_playback_thread(
    message_rx: Receiver<ProcessingMessage>,
    command_rx: Receiver<PlaybackCommand>,
    event_tx: Sender<ThreadEvent>,
    sample_rate: u32,
    buffer_ms: u32,
    initial_channels: usize,
    frame_size: usize,
    output_device: Option<String>,
    recycle_tx: SyncSender<Vec<f32>>,
    allow_virtual_output: bool,
    output_access: OutputAccessMode,
) -> Result<(), String> {
    let mut runtime = PlaybackRuntime::new(PlaybackRuntimeParams {
        message_rx,
        command_rx,
        event_tx,
        sample_rate,
        buffer_ms,
        initial_channels,
        frame_size,
        output_device,
        recycle_tx,
        allow_virtual_output,
        output_access,
    })?;
    runtime.run()
}

